import{c as l,Q as o,J as r,h as e,e as a,m as i,l as n,k as d}from"./chunks/framework.WgZQdPFo.js";const _=JSON.parse('{"title":"О философии проекта","description":"Четыре фундаментальных принципа бережливого и точного управленческого учета ОмниКрафт ЕРП.","frontmatter":{"title":"О философии проекта","description":"Четыре фундаментальных принципа бережливого и точного управленческого учета ОмниКрафт ЕРП.","order":1},"headers":[],"relativePath":"ru/docs/introduction.md","filePath":"ru/docs/introduction.md","lastUpdated":1794188933000}'),c={name:"ru/docs/introduction.md"},p={id:"о-философии-проекта",tabindex:"-1"};function u(h,t,m,v,b,g){const s=o("DocIcon");return r(),e("div",null,[a("h1",p,[i(s,{name:"philosophy"}),t[0]||(t[0]=n(" О философии проекта ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#о-философии-проекта","aria-label":'Permalink to "<DocIcon name="philosophy" /> О философии проекта"'},"​",-1))]),t[2]||(t[2]=d('<p><strong>ОмниКрафт ЕРП</strong> создана для ремесленников и владельцев небольших производств. Классический бухучет спроектирован под требования налоговых органов: он перегружен бесконечными накладными, сложными планами счетов и отвлекает от живой работы у верстака.</p><p>В основу системы заложен инженерный прагматизм: учет должен помогать делу, требовать минимум времени и честно показывать реальную прибыль.</p><hr><h2 id="четыре-фундаментальных-принципа-омникрафт-ерп" tabindex="-1">Четыре фундаментальных принципа ОмниКрафт ЕРП <a class="header-anchor" href="#четыре-фундаментальных-принципа-омникрафт-ерп" aria-label="Permalink to &quot;Четыре фундаментальных принципа ОмниКрафт ЕРП&quot;">​</a></h2><h3 id="_1-автоматизация-вместо-бухгалтерии" tabindex="-1">1. Автоматизация вместо бухгалтерии <a class="header-anchor" href="#_1-автоматизация-вместо-бухгалтерии" aria-label="Permalink to &quot;1. Автоматизация вместо бухгалтерии&quot;">​</a></h3><p>Вам не придется сводить дебет с кредитом или собирать финансовые отчеты вручную. Аналитика рождается сама — из естественных повседневных действий:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet">✓</span><div><strong>Закупка:</strong> вы вносите оплату за кожу, дерево или металл — партия сразу встает на склад, а расходы на доставку автоматически распределяются в цену каждого дециметра или килограмма.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Производство:</strong> материалы списываются по скользящей средней стоимости (МАК), сохраняя точную себестоимость изделий даже при резких скачках цен у поставщиков.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Отгрузка:</strong> готовая продукция списывается по методу первых партий (ФИФО), в журнале фиксируется выручка, а система мгновенно рассчитывает чистую маржу сделки.</div></li></ul><div class="info custom-block"><p class="custom-block-title">Принцип непрерывного учета</p><p>Система исключает двойную работу. Вы отмечаете факт (приняли сырье, скроили партию, передали заказ клиенту) — остатки на складе, касса и баланс пересчитываются моментально.</p></div><h3 id="_2-смешанные-финансы-без-лишнеи-бюрократии" tabindex="-1">2. Смешанные финансы без лишней бюрократии <a class="header-anchor" href="#_2-смешанные-финансы-без-лишнеи-бюрократии" aria-label="Permalink to &quot;2. Смешанные финансы без лишней бюрократии&quot;">​</a></h3><p>Учебники по учету настаивают на жестком разделении личного кошелька и кассы компании. Но в практике малых мастерских это выливается в пустые хлопоты: клей и фурнитуру часто оплачивают личной банковской картой, а выручку за готовое изделие тратят на текущие домашние покупки.</p><p>В ОмниКрафт ЕРП смешанные финансовые потоки поддержаны как естественная норма:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet">✓</span><div><strong>Учитываются только операции дела:</strong> материалы, станки, аренда и выручка. Не нужно плодить фиктивные переводы и записывать в базу каждую бытовую покупку.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Минус по кассе — это ваши инвестиции:</strong> отрицательный остаток в отчете ДДС означает лишь то, что мастерская временно работает на ваши личные вложения. Когда денежный поток выходит в плюс — проект окупил стартовые затраты и начал отдавать чистую прибыль.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Математическая строгость расчетов:</strong> себестоимость вещей, окупаемость вашего рабочего часа и общая капитализация считаются точно, независимо от того, с какого счета переведены деньги поставщикам.</div></li></ul><div class="tip custom-block"><p class="custom-block-title">Плавный переход к раздельному счету</p><p>Если со временем появится отдельный расчетный счет ИП или корпоративная карта, система готова к этому без перенастройки. Достаточно использовать стандартные статьи движения денег: <strong>«Пополнение бизнеса (инвестиции)»</strong> и <strong>«Списание на личное (вывод прибыли)»</strong>.</p></div><h3 id="_3-баланс-активов-и-реальныи-финансовыи-результат" tabindex="-1">3. Баланс активов и реальный финансовый результат <a class="header-anchor" href="#_3-баланс-активов-и-реальныи-финансовыи-результат" aria-label="Permalink to &quot;3. Баланс активов и реальный финансовый результат&quot;">​</a></h3><p>Покупка японского рубанка, лазерного гравера или муфельной печи уменьшает сумму на банковской карте, но имущество вашего дела никуда не исчезает — свободные рубли просто переходят в форму надежного оборудования.</p><p>Баланс собирается непрерывно и в реальном времени:</p><div class="craft-callout craft-callout-info"><div class="callout-header">Формула чистых активов (Собственный капитал)</div><p><strong>Собственный капитал</strong> = Остаточная стоимость оборудования + Сырье на складе (по скользящей средней стоимости) + Готовые изделия (по себестоимости) + Свободный остаток на счетах − Обязательства и долги.</p></div><h4 id="триединство-финансовых-отчетов" tabindex="-1">Триединство финансовых отчетов <a class="header-anchor" href="#триединство-финансовых-отчетов" aria-label="Permalink to &quot;Триединство финансовых отчетов&quot;">​</a></h4><p>Три базовых показателя дополняют друг друга и спасают от кассовых разрывов и ложного ощущения успеха:</p><div class="comparison-matrix-wrapper"><table class="craft-comparison-table"><thead><tr><th style="width:24%;">Отчет</th><th style="width:32%;">Главный вопрос</th><th style="width:44%;">Практический смысл у верстака</th></tr></thead><tbody><tr><td><strong>ДДС</strong><br><small style="color:var(--vp-c-text-3);">Движение денег</small></td><td><em>Есть ли средства прямо сейчас?</em></td><td>Отражает физический поток наличных и безналичных переводов. Помогает вовремя заметить кассовый разрыв и не остаться без денег на аренду.</td></tr><tr><td><strong>Прибыль (ОПиУ)</strong><br><small style="color:var(--vp-c-text-3);">Финансовый результат</small></td><td><em>Выгодно ли то, что вы делаете?</em></td><td>Сравнивает доходы с полными затратами (с учетом амортизации станков, израсходованных запасов и налогов). Показывает, окупаются ли ваши усилия.</td></tr><tr><td><strong>Баланс</strong><br><small style="color:var(--vp-c-text-3);">Чистые активы</small></td><td><em>Сколько стоит все ваше дело?</em></td><td>Суммирует все имущество (станки, сырье, склад готового) за вычетом долгов. Демонстрирует, растет ли ценность мастерской из года в год.</td></tr></tbody></table></div><div class="tip custom-block"><p class="custom-block-title">Автоматические снимки состояния</p><p>Система регулярно сохраняет слепки ключевых метрик. Это позволяет наблюдать динамику: отслеживать сезонные колебания внутри месяца и стратегический рост капитала по годам.</p></div><h3 id="_4-приватныи-ии-помощник-прямого-доступа-со-своим-ключом" tabindex="-1">4. Приватный ИИ-помощник прямого доступа (со своим ключом) <a class="header-anchor" href="#_4-приватныи-ии-помощник-прямого-доступа-со-своим-ключом" aria-label="Permalink to &quot;4. Приватный ИИ-помощник прямого доступа (со своим ключом)&quot;">​</a></h3><p>Встроенный интеллектуальный помощник работает по принципу прямого доступа: вы подключаете собственный ключ к нейросети, а обработка данных идет без промежуточных серверов.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet">✓</span><div><strong>Прямая связь без внешних серверов:</strong> запросы идут с вашего компьютера напрямую к провайдерам (`OpenAI`, `DeepSeek`, `Google Gemini`, `OpenRouter`) либо исполняются локально через службу `Ollama`. Рецепты, себестоимость и клиентские контакты никогда не попадают на серверы разработчиков.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Умные помощники на рабочих местах:</strong> компактные кнопки встроены в ключевые формы — экспресс-проверка структуры сметы в калькуляторе, технологические шпаргалки на верстаке и составление описаний для складских позиций.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Контроль за человеком:</strong> боковая панель видит активную вкладку и данные открытого заказа, но ни одной записи в базе не изменит без вашей ручной команды (принцип обязательного подтверждения человеком).</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Интеграция через протокол `Model Context Protocol` (`MCP`):</strong> поддерживается открытый стандарт прямого подключения программы к автономным инженерным средам (`Cursor`, `Claude Desktop`, `Antigravity`).</div></li></ul>',24))])}const k=l(c,[["render",u]]);export{_ as __pageData,k as default};
